import pytest
from wordfreq import text_word_frequency_ranking

def test_empty_text():
    assert text_word_frequency_ranking("", 3) == []

def test_single_word():
    assert text_word_frequency_ranking("hello", 1) == [("hello", 1)]

def test_multiple_words():
    assert text_word_frequency_ranking("hello world hello", 2) == [("hello", 2), ("world", 1)]

def test_case_insensitive():
    assert text_word_frequency_ranking("Hello HELLO hello", 2) == [("hello", 3)]

def test_words_with_apostrophes():
    assert text_word_frequency_ranking("don't stop", 2) == [("don't", 1), ("stop", 1)]

def test_ties_sorted_alphabetically():
    assert text_word_frequency_ranking("apple banana apple banana", 2) == [("apple", 2), ("banana", 2)]

@pytest.mark.parametrize("n", [-1, 0])
def test_n_zero_or_negative(n):
    with pytest.raises(ValueError):
        text_word_frequency_ranking("hello world", n)

def test_more_requested_than_available():
    assert text_word_frequency_ranking("hello world", 5) == [("hello", 1), ("world", 1)]

def test_text_with_punctuation():
    assert text_word_frequency_ranking("Hello, world! Hello.", 2) == [("hello", 2), ("world", 1)]
